func (fc *defaultVisibleFlagCategory) Flags() []Flag {
	vfNames := []string{}
	for flName, fl := range fc.m {
		if vf, ok := fl.(VisibleFlag); ok {
			if vf.IsVisible() {
				vfNames = append(vfNames, flName)
			}
		}
	}

	sort.Strings(vfNames)

	ret := make([]Flag, len(vfNames))
	for i, flName := range vfNames {
		ret[i] = fc.m[flName]
	}

	return ret
}
